def main():
    students = {
        "u-17": {"name": "Aylin", "scores": [90, 84]},
        "u-23": {"name": "Murad", "scores": [72, 95]},
    }
    for user_id, student in students.items():
        average = sum(student["scores"]) / len(student["scores"])
        print(user_id, student["name"], round(average, 1))
    passed = {
        user_id: student["name"]
        for user_id, student in students.items()
        if sum(student["scores"]) / len(student["scores"]) >= 80
    }
    print(passed)

if __name__ == "__main__":
    main()
